import {CARDS} from './content.js';
import {art,guideArt} from './illustrations.js';
export function cardStacks(cards){const stacks=new Map();cards.forEach((key,index)=>{if(stacks.has(key))stacks.get(key).count++;else stacks.set(key,{key,index,count:1});});return [...stacks.values()];}
export function cardsPanel(g){
 const p=g.s.players[0],reasonFor=key=>!p.alive?'你已退出本局':g.player.id!==p.id?'电脑回合，查看你的卡包':g.cardHint(key),stacks=cardStacks(p.cards),ready=stacks.filter(({key})=>!reasonFor(key)).length;
 return `${guideArt('dice','移动卡在掷骰前用；抢地卡仅抵达对手地产、付租前使用；建设、拆除和免租可在行动前后使用。选卡后会显示目标与效果。')}<div class="card-bag-summary"><strong>${p.cards.length}<small> / 15 张</small></strong><span>${stacks.length} 种道具<br>${ready+' 种当前可用'} · 我的卡包</span></div><div class="collectible-grid">${stacks.length?stacks.map(({key,index,count})=>{const c=CARDS[key],reason=reasonFor(key),timing=key==='steal'?'抵达付租前':['dice','turn','slow','block'].includes(key)?'出发前':'行动前后';return `<article class="row collectible-card bag-card ${reason?'card-unavailable':'card-ready'}"><div class="card-heading"><span class="card-timing">${timing}</span><b class="card-quantity" aria-label="拥有 ${count} 张">×${count}</b></div>${art(key)}<h3>${c.name}</h3><p>${c.description}</p><div class="card-availability">${reason||(!p.human?'电脑回合中':c.target==='self'?'使用后立即生效':'选择地图目标')}</div><button class="${reason?'secondary':'primary'}" data-act="card" data-index="${index}" ${reason||!p.human?'disabled':''}>${reason?'暂不可用':c.target==='self'?'使用卡片':'选择目标'}</button></article>`;}).join(''):'<div class="empty">卡包空空的，到地图上的商店补给吧。</div>'}</div>`;
}
